<?php require_once __DIR__.'/config/config.php'; layout_header('Image Check'); $rows=db()->query("SELECT id,name,category,image_url FROM products ORDER BY category,name")->fetchAll(); ?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="fw-bold">Product Image Check</h1><p class="text-muted mb-0">Every product is matched to a real Flickr photo using its product name.</p></div><a class="btn btn-success" href="products.php">Back to Products</a></div>
<div class="row g-4"><?php foreach($rows as $p): ?><div class="col-6 col-md-4 col-lg-3"><div class="card h-100 shadow-sm"><div class="product-img"><img src="<?=e(product_image($p['name'],$p['category'],$p['image_url']))?>" alt="<?=e($p['name'])?>" loading="lazy" onerror="this.onerror=null;this.src='assets/img-placeholder.svg';"></div><div class="card-body"><small class="text-success"><?=e($p['category'])?></small><h6 class="mt-1 mb-0"><?=e($p['name'])?></h6></div></div></div><?php endforeach; ?></div><?php layout_footer(); ?>